static int __anal_hint_range_tree_cmp(const void *a_, const RBNode *b_) {
        const RAnalRange *a = a_;
        const RAnalRange *b = container_of (b_, const RAnalRange, rb);
        if (a && b) {
                ut64 from0 = a->from, from1 = b->from;
                return from0 < from1 ? -1 : 1;
