static RAnalRange *__anal_range_hint_tree_find_at(RBNode *node, ut64 addr) {
        while (node) {
                RAnalRange *range = container_of (node, RAnalRange, rb);
                if (range->from == addr) {
                        return range;
                }
                node = node->child[range->from < addr];
        }
        return NULL;
}

